/// Return a line diff that turns the list of lines a into the list b.
/// Each entry is a two-character prefix plus a line: "  " (two spaces) for a
/// line kept from both lists, "- " for a line of a that is removed, "+ " for
/// a line of b that is added. Lines are compared exactly (whitespace and case
/// matter). The kept lines form a longest common subsequence of a and b,
/// chosen like this: walk both lists from the front; if the next lines of a
/// and b are equal, keep that line; otherwise, if removing the next line of a
/// leaves the remainders with a common subsequence as long as before, remove
/// it, else add the next line of b. Once one list is used up, remove or add
/// the rest of the other in order. So on a tie, removals come before
/// additions.
/// If the diff has no removed or added lines at all (including when both
/// lists are empty), return an empty vector, whatever context is.
/// If context is negative, return the whole diff. Otherwise a kept line stays
/// only if some removed or added entry is at most context positions away from
/// it in the whole diff; each maximal run of consecutive kept lines that do
/// not stay is replaced by the single entry "... N unchanged", where N is the
/// number of lines in the run (also when N is 1).
/// >>> line_diff(vec![String::from("a"), String::from("b"), String::from("c")], vec![String::from("a"), String::from("c"), String::from("d")], -1)
/// vec![String::from("  a"), String::from("- b"), String::from("  c"), String::from("+ d")]
/// >>> line_diff(vec![String::from("1"), String::from("2"), String::from("3"), String::from("4"), String::from("5"), String::from("x")], vec![String::from("1"), String::from("2"), String::from("3"), String::from("4"), String::from("5"), String::from("y")], 1)
/// vec![String::from("... 4 unchanged"), String::from("  5"), String::from("- x"), String::from("+ y")]
fn line_diff(a: Vec<String>, b: Vec<String>, context: isize) -> Vec<String> {
    let (n, m) = (a.len(), b.len());
    // lcs[i][j] = length of a longest common subsequence of a[i..] and b[j..]
    let mut lcs = vec![vec![0usize; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            lcs[i][j] = if a[i] == b[j] {
                lcs[i + 1][j + 1] + 1
            } else {
                lcs[i + 1][j].max(lcs[i][j + 1])
            };
        }
    }
    let mut full: Vec<String> = Vec::new();
    let (mut i, mut j) = (0, 0);
    while i < n || j < m {
        if i < n && j < m && a[i] == b[j] {
            full.push(format!("  {}", a[i]));
            i += 1;
            j += 1;
        } else if i < n && (j == m || lcs[i + 1][j] == lcs[i][j]) {
            full.push(format!("- {}", a[i]));
            i += 1;
        } else {
            full.push(format!("+ {}", b[j]));
            j += 1;
        }
    }
    let changed: Vec<isize> = (0..full.len())
        .filter(|&k| !full[k].starts_with("  "))
        .map(|k| k as isize)
        .collect();
    if changed.is_empty() {
        return Vec::new();
    }
    if context < 0 {
        return full;
    }
    let mut out = Vec::new();
    let mut hidden = 0;
    for (k, e) in full.into_iter().enumerate() {
        let k = k as isize;
        let stays = !e.starts_with("  ") || changed.iter().any(|&c| (k - c).abs() <= context);
        if stays {
            if hidden > 0 {
                out.push(format!("... {} unchanged", hidden));
                hidden = 0;
            }
            out.push(e);
        } else {
            hidden += 1;
        }
    }
    if hidden > 0 {
        out.push(format!("... {} unchanged", hidden));
    }
    out
}
